package com.marketradar.app

import org.json.JSONArray
import org.json.JSONObject
import java.time.LocalDate
import java.time.OffsetDateTime
import java.time.ZoneOffset
import java.time.format.DateTimeFormatter

/**
 * Implied-EV v1.2 Paper experiment: Rule B (paper_rule_b_v1) planned exit, native port of
 * ev_v12_lifecycle.rule_b_exit_step (Python is the reference; parity is pinned by the shared vectors in
 * app/src/test/resources/ev_v12/rule_b_vectors.json, generated by tools/ev_rule_b_vectors.py).
 *
 * Planned exit: first valid executable close in [15:15, 15:28) IST on the planned exit session. Otherwise
 * LATE_EXIT_PENDING, retried in [09:20, 15:28) on later sessions, and UNRESOLVED at 15:28 IST on expiry day.
 * An unknown policy id fails closed (no action). Terminal states never change. Paper only: the caller
 * (PositionTickService) applies it only to paper trades whose entry_snapshot names this policy.
 */
object RuleBExitPolicy {
    const val POLICY_ID = "paper_rule_b_v1"
    const val MAX_LEG_QUOTE_AGE_MS = 120_000.0
    private const val FUTURE_TOLERANCE_MS = 5_000.0
    private val IST: ZoneOffset = ZoneOffset.ofHoursMinutes(5, 30)
    private val EXIT_WINDOW = 15 * 3600 + 15 * 60 to 15 * 3600 + 28 * 60
    private val LATE_WINDOW = 9 * 3600 + 20 * 60 to 15 * 3600 + 28 * 60

    /** Same list as ev_v12_calendar.NSE_HOLIDAYS_2026 / brain _CONST NSE_HOLIDAYS (NSE/FAOP/71777); test-pinned. */
    val NSE_HOLIDAYS_2026: Set<String> = setOf(
        "2026-01-26", "2026-03-03", "2026-03-26", "2026-03-31",
        "2026-04-03", "2026-04-14", "2026-05-01", "2026-05-28",
        "2026-06-26", "2026-09-14", "2026-10-02", "2026-10-20",
        "2026-11-10", "2026-11-24", "2026-12-25",
    )

    data class Leg(val qty: Int, val instrumentKey: String)
    data class Position(val policyId: String?, val state: String?, val plannedExitSession: String,
                        val expiry: String, val legs: List<Leg>)
    data class LegQuote(val bid: Double?, val ask: Double?, val tsMs: Double?)
    data class Tick(val tsIso: String, val quotes: Map<String, LegQuote>)
    data class FillLeg(val instrumentKey: String, val qty: Int, val price: Double, val bid: Double, val ask: Double,
                       val quoteTsMs: Double)
    data class Fill(val kind: String, val tsIso: String, val legs: List<FillLeg>, val closeValuePts: Double)
    data class Step(val state: String?, val action: String, val reason: String, val fill: Fill? = null)

    class CalendarUnavailable(msg: String) : Exception(msg)

    fun isSession(d: LocalDate): Boolean {
        if (d.year != 2026) throw CalendarUnavailable("CALENDAR_YEAR_NOT_COVERED")
        return d.dayOfWeek.value <= 5 && d.toString() !in NSE_HOLIDAYS_2026
    }

    private fun finite(x: Double?): Double? = x?.takeIf { it.isFinite() }

    fun legQuoteValid(q: LegQuote?, nowMs: Double): Boolean {
        if (q == null) return false
        val b = finite(q.bid) ?: return false
        val a = finite(q.ask) ?: return false
        val ts = finite(q.tsMs) ?: return false
        if (b <= 0 || a <= 0 || a < b) return false
        if (ts > nowMs + FUTURE_TOLERANCE_MS || nowMs - ts > MAX_LEG_QUOTE_AGE_MS) return false
        return true
    }

    fun step(position: Position, tick: Tick): Step {
        if (position.policyId != POLICY_ID) return Step(position.state, "NONE", "POLICY_UNKNOWN")
        var state = position.state ?: "OPEN"
        if (state == "EXIT_FILLED" || state == "UNRESOLVED") return Step(state, "NONE", "TERMINAL")
        val ts = OffsetDateTime.parse(tick.tsIso).withOffsetSameInstant(IST)
        val nowMs = ts.toInstant().toEpochMilli().toDouble() + ts.nano % 1_000_000 / 1e6
        val day = ts.toLocalDate()
        val planned = LocalDate.parse(position.plannedExitSession)
        val expiry = LocalDate.parse(position.expiry)
        val t = ts.hour * 3600 + ts.minute * 60 + ts.second
        val session = try { isSession(day) } catch (e: CalendarUnavailable) {
            return Step(state, "NONE", "CALENDAR_UNAVAILABLE")
        }
        if (day.isAfter(expiry) || (day == expiry && t >= LATE_WINDOW.second)) {
            return Step("UNRESOLVED", "MARK_UNRESOLVED", "NO_VALID_QUOTE_BY_EXPIRY_DEADLINE")
        }
        var kind: String? = null
        if (state == "OPEN") {
            if (day.isBefore(planned)) return Step("OPEN", "NONE", "BEFORE_PLANNED_SESSION")
            if (day == planned && t < EXIT_WINDOW.first) return Step("OPEN", "NONE", "BEFORE_EXIT_WINDOW")
            if (day == planned && t < EXIT_WINDOW.second) kind = "PLANNED_EXIT" else state = "LATE_EXIT_PENDING"
        }
        val markLate = if (position.state != "LATE_EXIT_PENDING") "MARK_LATE" else "NONE"
        if (state == "LATE_EXIT_PENDING") {
            if (day == planned || !session || t < LATE_WINDOW.first || t >= LATE_WINDOW.second) {
                return Step("LATE_EXIT_PENDING", markLate, "OUTSIDE_LATE_WINDOW")
            }
            kind = "LATE_EXIT"
        }
        if (!session) return Step(state, "NONE", "NOT_A_SESSION")
        val fills = ArrayList<FillLeg>()
        for (leg in position.legs) {
            val q = tick.quotes[leg.instrumentKey]
            if (!legQuoteValid(q, nowMs)) {
                return if (kind == "PLANNED_EXIT") Step("OPEN", "NONE", "LEG_QUOTE_INVALID")
                else Step("LATE_EXIT_PENDING", markLate, "LEG_QUOTE_INVALID")
            }
            val px = if (leg.qty < 0) q!!.ask!! else q!!.bid!!
            fills.add(FillLeg(leg.instrumentKey, leg.qty, px, q.bid!!, q.ask!!, q.tsMs!!))
        }
        val close = fills.sumOf { it.qty * it.price }
        return Step("EXIT_FILLED", "FILL", kind!!, Fill(kind, ts.format(DateTimeFormatter.ISO_OFFSET_DATE_TIME), fills, close))
    }

    // ---------- JSON adapters (shared vector format) ----------
    fun positionFromJson(o: JSONObject): Position {
        val legs = o.optJSONArray("legs") ?: JSONArray()
        return Position(
            o.optString("policy_id").ifBlank { null },
            if (o.isNull("state")) null else o.optString("state").ifBlank { null },
            o.optString("planned_exit_session"), o.optString("expiry"),
            (0 until legs.length()).map { i ->
                val l = legs.getJSONObject(i); Leg(l.getInt("qty"), l.getString("instrument_key"))
            })
    }

    fun tickFromJson(o: JSONObject): Tick {
        val q = o.optJSONObject("quotes") ?: JSONObject()
        val m = HashMap<String, LegQuote>()
        for (k in q.keys()) {
            val v = q.optJSONObject(k) ?: continue
            fun d(n: String): Double? = if (v.has(n) && !v.isNull(n)) v.optDouble(n) else null
            m[k] = LegQuote(d("bid"), d("ask"), d("ts_ms"))
        }
        return Tick(o.getString("ts_iso"), m)
    }

    fun stepToJson(s: Step): JSONObject = JSONObject().apply {
        put("state", s.state ?: JSONObject.NULL)
        put("action", s.action)
        put("reason", s.reason)
        s.fill?.let { f ->
            put("fill", JSONObject().apply {
                put("kind", f.kind); put("ts_iso", f.tsIso); put("close_value_pts", f.closeValuePts)
                put("legs", JSONArray(f.legs.map { l -> JSONObject().apply {
                    put("instrument_key", l.instrumentKey); put("qty", l.qty); put("price", l.price)
                    put("bid", l.bid); put("ask", l.ask); put("quote_ts_ms", l.quoteTsMs)
                } }))
            })
        }
    }

    /** Rule B trade? (Paper only; entry_snapshot.position_policy_id names this policy.) */
    fun isRuleBTrade(trade: JSONObject): Boolean {
        if (!trade.optBoolean("paper", false)) return false
        val es = trade.opt("entry_snapshot") ?: trade.opt("entrySnapshot")
        val obj = when (es) {
            is JSONObject -> es
            is String -> try { JSONObject(es) } catch (e: Exception) { null }
            else -> null
        } ?: return false
        return obj.optString("position_policy_id") == POLICY_ID
    }

    /** Experiment policy identities this build knows how to execute. */
    val KNOWN_EXPERIMENT_POLICIES: Set<String> = setOf(POLICY_ID)

    enum class PolicyClass { LEGACY, RULE_B, UNKNOWN_EXPERIMENT }

    /**
     * Codex R2: which exit policy governs a trade. Paper trades whose entry_snapshot names a known experiment
     * policy are RULE_B; a Paper trade naming any OTHER non-blank position_policy_id is UNKNOWN_EXPERIMENT and
     * fails closed (no legacy alerts, no fills). Everything else, including every Real trade and every older
     * non-experiment Paper trade, stays LEGACY and is byte-identical to before.
     */
    fun policyClass(trade: JSONObject): PolicyClass {
        if (!trade.optBoolean("paper", false)) return PolicyClass.LEGACY
        val id = policyOf(trade)?.optString("position_policy_id")?.trim().orEmpty()
        return when {
            id.isEmpty() -> PolicyClass.LEGACY
            id in KNOWN_EXPERIMENT_POLICIES -> PolicyClass.RULE_B
            else -> PolicyClass.UNKNOWN_EXPERIMENT
        }
    }

    /** Published row action for an experiment trade (the legacy action is kept as an informational trace only). */
    fun publishedAction(step: Step?): String = when {
        step == null -> "RULE_B_HOLD"
        step.state == "EXIT_FILLED" -> "RULE_B_EXIT_FILLED"
        step.state == "UNRESOLVED" -> "RULE_B_UNRESOLVED"
        step.state == "LATE_EXIT_PENDING" -> "RULE_B_LATE_EXIT_PENDING"
        else -> "RULE_B_HOLD"
    }

    fun policyOf(trade: JSONObject): JSONObject? {
        val es = trade.opt("entry_snapshot") ?: trade.opt("entrySnapshot")
        return when (es) {
            is JSONObject -> es
            is String -> try { JSONObject(es) } catch (e: Exception) { null }
            else -> null
        }
    }
}
